#include <stdio.h>
#include <string.h>

int main() {
    const char *names[] = {"mango", "apple", "cherry", "banana"};
    int n = 4;
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (strcmp(names[j], names[j + 1]) > 0) {
                const char *temp = names[j];
                names[j] = names[j + 1];
                names[j + 1] = temp;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        printf("%s\n", names[i]);
    }
    return 0;
}
